__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"questTips",{enumerable:!0,get:function(){return n}}),Object.defineProperty(e,"categoryTips",{enumerable:!0,get:function(){return t}}),e.questTipFor=function(s,u){return n[s]??t[u]};const n={'glut-01':'Langsam, so weit es angenehm ist.','glut-02':'Die Schultern d\xfcrfen dabei schwer werden.','glut-03':'Ein Glas in Sichtweite ist schon ein guter Schritt.','glut-04':'Beim Ausatmen ruhig etwas l\xe4nger bleiben.','glut-05':'H\xe4nde in den Scho\xdf, Schultern locker.','glut-06':'Nimm das, was dir zuerst ins Auge f\xe4llt.','glut-07':'Fenster auf, wenn es geht, und einmal tief einatmen.','glut-08':'Niemand erwartet einen langen Text.','glut-09':'Kleine \xc4nderung, sp\xfcrbarer Unterschied.','glut-10':'Zum Beispiel: Heute reicht auch wenig.','glut-11':'Neugier z\xe4hlt, Gr\xfcndlichkeit nicht.','glut-12':'Handy umdrehen hilft.','glut-13':'Dein Morgen-Ich sagt Danke.','glut-14':'Bleib ruhig einen Atemzug l\xe4nger dabei.','meditation-eine-minute':'Augen zu oder ein fester Punkt vor dir: beides ist richtig.','journal-morgen':'Kein Plan ist auch eine Antwort. Ehrlich z\xe4hlt mehr als vollst\xe4ndig.','journal-abend':'Auch ein schwerer Tag darf einfach so stehen bleiben.',quest_001:'Leg dir die Schuhe schon an die T\xfcr, dann ist der erste Schritt fast von allein gemacht.',quest_002:'Dehne nur so weit, wie es angenehm ist, und atme dabei ruhig weiter.',quest_003:'Fang mit einem Stockwerk an, den Rest darf der Aufzug \xfcbernehmen.',quest_004:'Eine Runde um den Block reicht v\xf6llig, Hauptsache, du kommst kurz raus.',quest_005:'Kreise langsam Schultern, H\xfcfte und Fu\xdfgelenke, ganz ohne Eile.',quest_006:'Stell dir einen Wecker f\xfcr die Pause, dann vergisst du sie nicht im Trubel.',quest_007:'Auch ein kurzer Weg zum B\xe4cker z\xe4hlt als Radtour.',quest_008:'Biege einmal anders ab als sonst, schon ist es eine neue Strecke.',quest_009:'Wenige saubere Wiederholungen sind mehr wert als viele hastige.',quest_010:'W\xe4hle ein Lied, das du magst, und beweg dich, bis es zu Ende ist.',quest_011:'Eine Handvoll Tiefk\xfchlgem\xfcse ist schnell dazugegeben.',quest_012:'Nimm beim n\xe4chsten Einkauf einfach eine Sorte mit, die du noch nicht kennst.',quest_013:'Bohnen, Linsen oder N\xfcsse lassen sich leicht in Gewohntes mischen.',quest_014:'Ein einfaches Rezept mit wenigen Zutaten ist genau richtig f\xfcr den Anfang.',quest_015:'Probier beim Brot oder bei Nudeln einmal die Vollkornvariante.',quest_016:'Tausch eine Zutat in einem Lieblingsgericht gegen etwas Neues.',quest_017:'Leg das Handy beim Essen zur Seite und nimm dir ein paar Minuten.',quest_018:'Halte vor dem Nachschlag kurz inne und frag dich, wie es dir gerade geht.',quest_019:'Schneide schon am Abend etwas vor, dann geht es morgen schneller.',quest_020:'Mach ein Foto vom Rezept, dann findest du es sp\xe4ter wieder.',quest_021:'Stell dir das Glas dorthin, wo du es sicher siehst.',quest_022:'F\xfclle die Flasche direkt am Morgen, dann steht sie bereit.',quest_023:'Verbinde die Trinkpause mit etwas, das du ohnehin tust, etwa dem Kaffee.',quest_024:'Pack die Flasche gleich zu Schl\xfcssel und Geldbeutel.',quest_025:'Ein Schluck zu jeder vollen Stunde ist ein guter Rhythmus.',quest_026:'Ein Glas in Reichweite wird viel \xf6fter benutzt als eines in der K\xfcche.',quest_027:'Stell dir schon vor der Bewegung etwas zu trinken bereit.',quest_028:'Eine Erinnerung am Handy reicht, zwei oder drei am Tag sind genug.',quest_029:'Zum Beispiel: nach jedem H\xe4ndewaschen ein paar Schlucke.',quest_030:'Eine kleine Flasche passt in fast jede Tasche.',quest_031:'Ein Glas Wasser und ein Blick aus dem Fenster sind schon ein guter Start.',quest_032:'Streich einen Schritt aus deiner Abendroutine, der dich nur stresst.',quest_033:'Mach es zur gleichen Zeit wie gestern, das macht es leichter.',quest_034:'Frag dich: Was w\xfcrde den heutigen Tag f\xfcr mich gut machen?',quest_035:'Klein hei\xdft wirklich klein: eine Nachricht, ein Anruf, ein Handgriff.',quest_036:'Was weniger als zwei Minuten dauert, erledigst du am besten sofort.',quest_037:'Ein H\xe4kchen oder ein Wort im Kalender reicht schon.',quest_038:'Leg dir abends hin, was du morgens brauchst.',quest_039:'Probier es eine Woche lang zur selben Uhrzeit und schau, wie es sich anf\xfchlt.',quest_040:'Eine Frage gen\xfcgt: Was war heute gut?',quest_041:'Stell einen Timer auf f\xfcnf Minuten, aufh\xf6ren ist danach ausdr\xfccklich erlaubt.',quest_042:'Schlie\xdf alles, was du f\xfcr diese Aufgabe nicht brauchst.',quest_043:'Speichere Wichtiges als Lesezeichen, dann f\xe4llt das Schlie\xdfen leichter.',quest_044:'Leg das Handy in einen anderen Raum oder mit dem Bildschirm nach unten.',quest_045:'Schreib nur den allerersten Schritt auf, die n\xe4chsten ergeben sich.',quest_046:'Gut genug ist fertig, verbessern kannst du sp\xe4ter immer noch.',quest_047:'Nimm dir nur vor, die Aufgabe zu \xf6ffnen, mehr nicht.',quest_048:'Ein Notizzettel oder eine Sprachnachricht an dich selbst reicht.',quest_049:'Steh kurz auf, streck dich und schau in die Ferne.',quest_050:'Schalte eine Benachrichtigung aus, die dich oft unterbricht.',quest_051:'Stell einen Timer, wenn er klingelt, darfst du aufh\xf6ren.',quest_052:'Fang mit dem Gegenstand an, der dir als Erstes ins Auge f\xe4llt.',quest_053:'Nimm alles heraus und leg nur zur\xfcck, was du wirklich nutzt.',quest_054:'Ein freier Tisch und ein Glas Wasser sind ein guter Anfang.',quest_055:'Schl\xfcssel, Geldbeutel, Handy, alles Weitere ist Bonus.',quest_056:'W\xe4hle die Kleinigkeit, die dich am l\xe4ngsten begleitet.',quest_057:'L\xf6sche zuerst die offensichtlichen Doppelungen.',quest_058:'Schreib auf, was fast leer ist, solange du es noch wei\xdft.',quest_059:'Eine Ecke vom Tisch reicht schon.',quest_060:'Leg eine Kiste f\xfcr Dinge bereit, die gehen d\xfcrfen.',quest_061:'Z\xe4hle beim Ausatmen langsam bis vier.',quest_062:'Schlie\xdf kurz die Augen und sp\xfcr, wie deine F\xfc\xdfe den Boden ber\xfchren.',quest_063:'Halte ihn fest, mit einem Wort, einem Foto oder einfach in Gedanken.',quest_064:'Eine gef\xfchrte \xdcbung von wenigen Minuten ist ein guter Einstieg.',quest_065:'Drei kleine Dinge gen\xfcgen, auch ein guter Kaffee z\xe4hlt.',quest_066:'Schau aus dem Fenster statt auf einen Bildschirm.',quest_067:'Z\xe4hle, wie viele verschiedene Ger\xe4usche du h\xf6rst.',quest_068:'Sprich mit dir so, wie du mit einem guten Freund sprechen w\xfcrdest.',quest_069:'Frag dich: Was brauche ich gerade?',quest_070:'W\xe4hle etwas Allt\xe4gliches und nimm es mit allen Sinnen wahr.',quest_071:'\xd6ffne zuerst das Fenster, vielleicht wird daraus ein kurzer Gang vor die T\xfcr.',quest_072:'Ein Park, eine Stra\xdfe oder ein Caf\xe9, in dem du noch nie warst.',quest_073:'Ein Blatt, ein Stein oder eine Wolke, schau genau hin.',quest_074:'Achte auf Licht und Farben, das Motiv darf ganz klein sein.',quest_075:'Schon ein paar B\xe4ume am Stra\xdfenrand z\xe4hlen als Gr\xfcn.',quest_076:'Such nach Formen in den Wolken.',quest_077:'Nimm dein Getr\xe4nk mit nach drau\xdfen.',quest_078:'Markiere sie in deiner Karten-App, dann findest du sie wieder.',quest_079:'Am Vormittag tut das Licht besonders gut.',quest_080:'Achte auf Rinde, Bl\xe4tter und wie sich alles bewegt.',quest_081:'Ein Satz reicht: \u201eIch habe gerade an dich gedacht.\u201c',quest_082:'Eine kurze Sprachnachricht ist oft leichter als ein Anruf.',quest_083:'Sag genau, wof\xfcr du dankbar bist, das freut besonders.',quest_084:'Schlag zwei m\xf6gliche Termine vor, das macht die Antwort leicht.',quest_085:'Frag einmal mehr nach, statt sofort zu antworten.',quest_086:'Lob etwas Konkretes, das dir wirklich aufgefallen ist.',quest_087:'Etwas Einfaches wie ein Spaziergang ist leicht zuzusagen.',quest_088:'Frag offen: \u201eWie geht es dir wirklich?\u201c',quest_089:'Ein kurzes \u201eKann ich dir helfen?\u201c gen\xfcgt.',quest_090:'Teile eine Erinnerung, die euch beide verbindet.',quest_091:'W\xe4hle ein Thema, das dich gerade neugierig macht.',quest_092:'Lies nur die ersten Seiten, oft liest du dann von selbst weiter.',quest_093:'Ein erster Versuch darf holprig sein, darum geht es ja.',quest_094:'Erkl\xe4r jemandem in zwei S\xe4tzen, was du gelernt hast.',quest_095:'Schreib die Frage zuerst auf, dann suchst du gezielter.',quest_096:'Drei Stichworte reichen v\xf6llig.',quest_097:'Ein kurzes Video zum Mitmachen ist ein guter Einstieg.',quest_098:'Schreib das Wort auf einen Zettel und benutze es heute einmal.',quest_099:'Versuch es erst aus dem Kopf, dann schau nach.',quest_100:'Hak den Schritt bewusst ab, das gibt einen sch\xf6nen Schub.',quest_101:'H\xe4nge sie an etwas, das du sowieso jeden Tag tust.',quest_102:'W\xe4hle etwas, das ein bisschen Mut braucht, aber machbar ist.',quest_103:'Eine Idee reicht, sie muss nicht perfekt sein.',quest_104:'Mach die Pause, bevor du sie dringend brauchst.',quest_105:'Frag dich: Welcher Schritt kann einfach wegfallen?',quest_106:'Etwas Kleines z\xe4hlt genauso, etwa ein Lieblingslied.',quest_107:'Schon zehn Minuten f\xfcr dein Hobby sind ein Geschenk an dich.',quest_108:'Ein freundlicher Satz mit \u201eIch\u201c wirkt besser als eine Rechtfertigung.',quest_109:'Leg einen neuen Termin fest, dann ist es kein Aufschieben, sondern ein Plan.',quest_110:'G\xf6nn dir etwas, das dir Freude macht, du hast es dir verdient.',spaziergang:'Leg dir die Schuhe schon an die T\xfcr, dann ist der erste Schritt fast von allein gemacht.',dehnen:'Dehne nur so weit, wie es angenehm ist, und atme dabei ruhig weiter.',treppe:'Steh kurz auf, streck dich und geh ein paar Schritte.',aufraeumen:'Stell einen Timer, wenn er klingelt, darfst du aufh\xf6ren.',lueften:'Ein paar Minuten weit offen bringen mehr als lange gekippt.',tagesplan:'Drei Stichworte reichen, morgen wei\xdft du dann, wo du anf\xe4ngst.',checkin:'Einchecken dauert nur einen Moment und z\xe4hlt trotzdem voll.','boss-fuenf-minuten-anfangen':'Stell einen Timer auf f\xfcnf Minuten, aufh\xf6ren ist danach ausdr\xfccklich erlaubt.','boss-bei-einer-sache-bleiben':'Leg alles beiseite, was nichts mit dieser einen Sache zu tun hat.','boss-gut-genug':'Gut genug ist fertig, verbessern kannst du sp\xe4ter immer noch.','boss-ein-punkt':'W\xe4hle den kleinsten Punkt auf deiner Liste.','boss-bequem-und-los':'Bequeme Kleidung bereitlegen ist schon der halbe Weg.','boss-kleiner-spaziergang':'Nimm den l\xe4ngeren Weg zum Briefkasten oder zur K\xfcche.','boss-lockern-oder-erholen':'H\xf6r auf deinen K\xf6rper, auch Erholung ist ein guter Schritt.','boss-etwas-gruenes':'Schon eine Zimmerpflanze oder ein Baum vor dem Fenster z\xe4hlt.','boss-kurz-innehalten':'Drei ruhige Atemz\xfcge reichen schon.','boss-mini-routine':'Die kleinste Version z\xe4hlt genauso, heute reicht ein Anfang.'},t={bewegung:'Fang mit der kleinsten Version an, mehr geht sp\xe4ter immer noch.',ernaehrung:'Eine kleine \xc4nderung an etwas Gewohntem ist der leichteste Anfang.',trinken:'Stell dir etwas zu trinken dorthin, wo du es sicher siehst.',routine:'H\xe4ng es an etwas, das du sowieso jeden Tag tust.',fokus:'Stell einen Timer, ein klarer Rahmen macht den Anfang leichter.',ordnung:'F\xfcnf Minuten gen\xfcgen, danach darfst du aufh\xf6ren.',achtsamkeit:'Ein paar ruhige Atemz\xfcge sind schon ein guter Anfang.',draussen:'Schon ein paar Minuten vor der T\xfcr z\xe4hlen.',soziales:'Ein kurzer Satz reicht, um jemandem eine Freude zu machen.',lernen:'W\xe4hle etwas, das dich gerade neugierig macht.',lebensweise:'Klein anfangen ist kein Umweg, sondern der Weg.',selbstfuersorge:'G\xf6nn dir etwas Kleines, das dir guttut.',checkin:'Einchecken dauert nur einen Moment und z\xe4hlt trotzdem voll.'}},915,[]);